/* Intercept course links before the browser changes the hash. */
document.addEventListener("click", event => {
  const link = event.target.closest("a[data-open-course]");
  if (!link) return;
  event.preventDefault();
  event.stopPropagation();
  openCourse(link.dataset.openCourse);
}, true);


/* =========================
   SQL PRACTICE LAB
   Uses SQL.js (SQLite/WASM) in the browser; no server database.
========================= */
let sqlEnginePromise;
let sqlInitialText = "SELECT * FROM Customers;";
const sqlExamples = {
 customers: "SELECT CustomerID, FullName, City FROM Customers ORDER BY FullName;",
 sales: "SELECT Status, COUNT(*) AS OrderCount, SUM(TotalAmount) AS Revenue FROM Orders GROUP BY Status ORDER BY Revenue DESC;",
 join: "SELECT c.FullName, o.OrderID, o.OrderDate, o.TotalAmount FROM Customers c JOIN Orders o ON o.CustomerID = c.CustomerID ORDER BY o.OrderDate DESC;",
 group: "SELECT p.ProductName, SUM(oi.Quantity) AS UnitsSold, SUM(oi.Quantity * oi.UnitPrice) AS Revenue FROM OrderItems oi JOIN Products p ON p.ProductID = oi.ProductID GROUP BY p.ProductID, p.ProductName ORDER BY Revenue DESC;"
};
function loadSqlEngine() {
  if (window.initSqlJs) return Promise.resolve(window.initSqlJs);
  if (sqlEnginePromise) return sqlEnginePromise;
  sqlEnginePromise = new Promise((resolve,reject)=>{
    const script=document.createElement("script");
    script.src="https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/sql-wasm.js";
    script.onload=()=>window.initSqlJs?resolve(window.initSqlJs):reject(new Error("کتابخانه SQL بارگذاری نشد"));
    script.onerror=()=>reject(new Error("دریافت موتور SQL ناموفق بود؛ اتصال اینترنت یا CDN را بررسی کن."));
    document.head.appendChild(script);
  });
  return sqlEnginePromise;
}
async function makePracticeDatabase() {
  const init=await loadSqlEngine();
  const SQL=await init({locateFile:file=>"https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.10.3/"+file});
  const db=new SQL.Database();
  db.run("CREATE TABLE Customers(CustomerID INTEGER PRIMARY KEY, FullName TEXT NOT NULL, City TEXT, CreatedAt TEXT);");
  db.run("CREATE TABLE Products(ProductID INTEGER PRIMARY KEY, ProductName TEXT NOT NULL, Category TEXT, Price NUMERIC, Stock INTEGER);");
  db.run("CREATE TABLE Orders(OrderID INTEGER PRIMARY KEY, CustomerID INTEGER, OrderDate TEXT, Status TEXT, TotalAmount NUMERIC, FOREIGN KEY(CustomerID) REFERENCES Customers(CustomerID));");
  db.run("CREATE TABLE OrderItems(OrderItemID INTEGER PRIMARY KEY, OrderID INTEGER, ProductID INTEGER, Quantity INTEGER, UnitPrice NUMERIC, FOREIGN KEY(OrderID) REFERENCES Orders(OrderID), FOREIGN KEY(ProductID) REFERENCES Products(ProductID));");
  db.run("INSERT INTO Customers VALUES (1,'مینا احمدی','تهران','2026-01-03'),(2,'علی رضایی','کرج','2026-01-08'),(3,'سارا محمدی','تهران','2026-02-11'),(4,'رضا کریمی','اصفهان','2026-02-15'),(5,'نگار حسینی','شیراز','2026-03-02'),(6,'آرمان صالحی','تبریز','2026-03-10');");
  db.run("INSERT INTO Products VALUES (1,'لپ‌تاپ','دیجیتال',45000000,8),(2,'ماوس','لوازم جانبی',850000,35),(3,'کیبورد','لوازم جانبی',2100000,18),(4,'مانیتور','دیجیتال',12500000,6),(5,'پایه لپ‌تاپ','لوازم جانبی',1600000,22),(6,'وب‌کم','دیجیتال',3200000,0);");
  db.run("INSERT INTO Orders VALUES (101,1,'2026-01-12','Paid',45850000),(102,2,'2026-01-18','Paid',2100000),(103,1,'2026-02-04','Paid',12500000),(104,3,'2026-02-12','Pending',6100000),(105,4,'2026-02-20','Cancelled',850000),(106,5,'2026-03-05','Paid',17600000),(107,2,'2026-03-14','Paid',1600000),(108,3,'2026-03-21','Paid',3200000);");
  db.run("INSERT INTO OrderItems VALUES (1,101,1,1,45000000),(2,101,2,1,850000),(3,102,3,1,2100000),(4,103,4,1,12500000),(5,104,2,2,850000),(6,104,5,2,1600000),(7,105,2,1,850000),(8,106,4,1,12500000),(9,106,5,2,1600000),(10,107,5,1,1600000),(11,108,6,1,3200000);");
  return db;
}
function initializeSqlLab() {
  const editor=document.getElementById("sqlEditor");
  const run=document.getElementById("runSqlBtn");
  const reset=document.getElementById("resetSqlBtn");
  if(!editor||!run||run.dataset.bound==="1") return;
  run.dataset.bound="1";
  const results=document.getElementById("sqlResults");
  const status=document.getElementById("sqlStatus");
  const showError=message=>{status.textContent="خطا در اجرای کوئری";results.textContent=message;};
  run.addEventListener("click",async()=>{
    run.disabled=true;status.textContent="در حال آماده‌سازی موتور SQL...";
    try {
      const db=await makePracticeDatabase();
      const statements=db.exec(editor.value);
      results.innerHTML="";
      if(!statements.length){results.textContent="دستور اجرا شد؛ خروجی جدولی ندارد.";status.textContent="اجرا موفق بود";db.close();return;}
      statements.forEach(result=>{
        const table=document.createElement("table");
        table.style.cssText="border-collapse:collapse;width:100%;font-size:13px";
        const thead=document.createElement("thead"),tr=document.createElement("tr");
        result.columns.forEach(col=>{const th=document.createElement("th");th.textContent=col;th.style.cssText="padding:9px;border:1px solid #d6e2f3;background:#eaf2ff;text-align:right";tr.appendChild(th);});
        thead.appendChild(tr);table.appendChild(thead);
        const tbody=document.createElement("tbody");
        result.values.forEach(row=>{const rr=document.createElement("tr");row.forEach(value=>{const td=document.createElement("td");td.textContent=value===null?"NULL":String(value);td.style.cssText="padding:8px;border:1px solid #e1e8f2;text-align:right";rr.appendChild(td);});tbody.appendChild(rr);});
        table.appendChild(tbody);results.appendChild(table);
        const note=document.createElement("p");note.textContent=result.values.length+" ردیف نمایش داده شد.";results.appendChild(note);
      });
      status.textContent="کوئری با موفقیت اجرا شد";
      db.close();
    } catch(error) {showError(error.message||String(error));}
    finally {run.disabled=false;}
  });
  reset.addEventListener("click",()=>{editor.value=sqlInitialText;status.textContent="کد نمونه بازنشانی شد";});
  document.querySelectorAll("[data-sql-example]").forEach(button=>button.addEventListener("click",()=>{
    editor.value=sqlExamples[button.dataset.sqlExample]||sqlInitialText;
    status.textContent="نمونه بارگذاری شد";
  }));
}
